<?php require_once __DIR__.'/../app/db.php'; require_once __DIR__.'/../app/layout.php'; require_login(); require_perm('*'); $pdo=pdo(); if($_SERVER['REQUEST_METHOD']==='POST'){ if(post('id')){ $sql='UPDATE users SET nom=?, identifiant=?, role=?, actif=?'.(post('mot_de_passe')?', mot_de_passe=?':'').' WHERE id=?'; $vals=[post('nom'),post('identifiant'),post('role'),post('actif')?1:0]; if(post('mot_de_passe'))$vals[]=password_hash(post('mot_de_passe'),PASSWORD_DEFAULT); $vals[]=post('id'); $pdo->prepare($sql)->execute($vals); } else {$pdo->prepare('INSERT INTO users(nom,identifiant,mot_de_passe,role,actif) VALUES(?,?,?,?,?)')->execute([post('nom'),post('identifiant'),password_hash(post('mot_de_passe'),PASSWORD_DEFAULT),post('role'),1]);} flash('Utilisateur enregistré.'); redirect('/users.php'); } $rows=$pdo->query('SELECT * FROM users ORDER BY id')->fetchAll(); render_header('Utilisateurs et accès'); ?><section class="panel"><h2>Créer un utilisateur</h2><form method="post" class="form-grid"><label>Nom<input name="nom" required></label><label>Identifiant<input name="identifiant" required></label><label>Mot de passe<input name="mot_de_passe" required></label><label>Rôle<select name="role"><option value="admin">Admin - accès total</option><option value="gerant">Gérant - supervision</option><option value="agent">Agent - clients/réservations</option><option value="comptable">Comptable - paiements/rapports</option><option value="mecanicien">Mécanicien - véhicules/maintenance</option></select></label><button class="btn primary">Ajouter</button></form></section><section class="panel"><h2>Comptes</h2><table><thead><tr><th>Nom</th><th>Identifiant</th><th>Rôle</th><th>Actif</th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td><?=e($u['nom'])?></td><td><?=e($u['identifiant'])?></td><td><?=e($u['role'])?></td><td><?=$u['actif']?'Oui':'Non'?></td></tr><?php endforeach;?></tbody></table><p class="muted">Les droits sont séparés : l’agent ne voit pas les utilisateurs, le comptable ne modifie pas les voitures, le mécanicien ne voit pas les paiements.</p></section><?php render_footer(); ?>
